# ── Helpers: safe extraction of element symbol and oxi_state ─────────────────
# pymatgen sites can hold either a Species object (ordered) or a Composition
# (disordered). These helpers handle both transparently.

def _site_element(site):
    """
    Return the majority element symbol for a site.
    For mixed-occupancy sites, returns the species with highest occupancy.
    """
    sp = site.species
    if len(sp) > 1:
        majority = max(sp.items(), key=lambda x: x[1])
        el = majority[0]
        return el.element.symbol if hasattr(el, 'element') else el.symbol
    if hasattr(sp, 'elements') and len(sp.elements) > 0:
        el = sp.elements[0]
        return el.symbol if hasattr(el, 'symbol') else str(el)
    return site.specie.element.symbol


def _site_oxi_state(site):
    """
    Return the oxidation state (float) for a site.
    For mixed-occupancy sites, returns the occupancy-weighted mean charge.
    """
    sp = site.species
    if len(sp) > 1:
        total_oxi = 0.0
        total_occ = 0.0
        for species, occ in sp.items():
            if hasattr(species, 'oxi_state'):
                total_oxi += species.oxi_state * occ
                total_occ += occ
        if total_occ > 0:
            return total_oxi / total_occ
        return 0.0
    if hasattr(sp, 'elements') and len(sp.elements) > 0:
        el = sp.elements[0]
        if hasattr(el, 'oxi_state'):
            return float(el.oxi_state)
    return float(site.specie.oxi_state)


def _is_anion_site(site):
    """
    Whether this site belongs to the anion sublattice.

    By oxidation state where the structure has them, and by element where it
    does not: load_structure asks about disorder before the states are
    assigned, and MaplePy's domain is oxides, so oxygen is the anion. Stated
    rather than assumed, because it is an assumption.
    """
    try:
        oxi = _site_oxi_state(site)
        if oxi:
            return oxi < 0
    except (AttributeError, TypeError, ValueError):
        pass
    return _site_element(site) == 'O'


def _disorder_detail(structure):
    """
    What kind of disorder this structure carries, and where: one computation.

    v1.3.3: `partial occupancy` was not enough. Making the flag see partial
    occupancy at all (v1.3.2) moved 14 oxygen-deficient refinements out of
    Hopper's oxygen non-stoichiometry class and into its disorder class, which
    describes them less well. Hopper has reserved a code for anion vacancy
    disorder since its first version and could not assign it without knowing
    which sublattice was short.

    MaplePy holds the occupancies, so MaplePy answers. Deriving this
    downstream from a reduced formula undercounts split sites, whose two
    half-occupied positions sum to an integer composition.

    Returns (kind, sublattice):
        kind        'ordered' | 'mixed occupancy' | 'partial occupancy'
                    | 'mixed and partial occupancy'
        sublattice  'none' | 'anion' | 'cation' | 'both'
    """
    mixed = False
    partial = set()
    for site in structure:
        if len(site.species) > 1:
            mixed = True
        if sum(site.species.values()) < FULL_OCCUPANCY_TOL:
            partial.add('anion' if _is_anion_site(site) else 'cation')

    sublattice = ('none' if not partial else
                  'both' if len(partial) > 1 else
                  next(iter(partial)))

    if mixed and partial:
        kind = 'mixed and partial occupancy'
    elif mixed:
        kind = 'mixed occupancy'
    elif partial:
        kind = 'partial occupancy'
    else:
        kind = 'ordered'
    return kind, sublattice


def _disorder_kind(structure):
    """The kind alone. Derived, so there is one computation."""
    return _disorder_detail(structure)[0]


def _is_disordered(structure):
    """True where the mean-field charge approximation is in use.

    Derived from _disorder_detail so there is one definition of disorder.
    """
    return _disorder_kind(structure) != 'ordered'


def _shortest_contact(structure):
    """
    The shortest interatomic distance in the cell, and the pair that makes it.

    Returns (d_ang, label_i, label_j). Any pair, not cation-anion: the fault
    this exists to catch is a same-element split site, which d_ref cannot see
    because d_ref only looks across the cation-anion boundary.
    """
    if len(structure) < 2:
        return float('inf'), None, None
    dm = structure.distance_matrix.copy()
    np.fill_diagonal(dm, np.inf)
    i, j = np.unravel_index(np.argmin(dm), dm.shape)
    return (float(dm[i, j]), _site_element(structure[int(i)]),
            _site_element(structure[int(j)]))


def _geometry_status(structure):
    """
    Whether the geometry can carry a Madelung energy, as a sentence.

    v1.3.2: MaplePy had no geometry test. Four structures in the 1410-entry
    dataset put two fractionally occupied sites within half an angstrom of
    each other, and their Ewald sums came out up to ten times the family
    median while being reported as ordinary results.

    v1.3.3: two thresholds, because the measured distribution has two
    populations - split sites below 0.5 A and coordinate errors between 1.0
    and 1.6 A, with nothing at all in between. See SPLIT_SITE_ANG and
    SHORT_CONTACT_ANG for both, and for which of them is a judgement.

    FLAG, KEEP, REPORT: this never drops a structure and never changes a
    number. It returns (d_min, flag, status): the flag for Hopper, which
    should not be matching on the prefix of a sentence, and the sentence for
    whoever reads the CSV.
    """
    d_min, el_i, el_j = _shortest_contact(structure)
    if d_min < SPLIT_SITE_ANG:
        return d_min, 'split_site', (
            f'split site: {el_i}-{el_j} contact {d_min:.3f} A, below '
            f'{SPLIT_SITE_ANG} A - the Ewald sum over these two sites is '
            f'not an energy')
    if d_min < SHORT_CONTACT_ANG:
        return d_min, 'short_contact', (
            f'short contact: {el_i}-{el_j} at {d_min:.3f} A, below '
            f'{SHORT_CONTACT_ANG} A - shorter than any cation-anion bond '
            f'these families produce, so the coordinates are suspect')
    return d_min, 'ok', f"ok: shortest contact {d_min:.3f} A"


# ── Oxidation state helpers (unchanged) ──────────────────────────────────────

def _load_oxi_json(path):
    """Load common_oxidation_states.json. {} if absent, raises if corrupt.

    v1.1: 'file is not there' and 'file is there and unreadable' are different
    facts and were both returning {}, which the priority chain below reads as
    'this source has nothing to say' and silently drops a level.
    """
    try:
        with open(path, 'r') as f:
            return json.load(f)
    except FileNotFoundError:
        return {}
    except (json.JSONDecodeError, OSError) as e:
        raise ValueError(f'{path} exists but could not be read: {e}') from e


def _load_maple_library(data_dir):
    # v1.3.1: no default. The directory is resolved once, in load_structure,
    # against DEFAULT_DATA_DIR; a second default here is a second answer to
    # the same question, and it was the wrong one.
    """Load maple_library.json. {} if absent, raises if corrupt. See above."""
    try:
        with open(Path(data_dir) / 'maple_library.json', 'r') as f:
            return json.load(f)
    except FileNotFoundError:
        return {}
    except (json.JSONDecodeError, OSError) as e:
        raise ValueError(
            f'maple_library.json in {data_dir} could not be read: {e}') from e


def _extract_cif_oxidation_states(cif_path):
    """
    Parse _atom_type_oxidation_number loop from a CIF file.

    Mirrors Eir's extract_cif_oxidation_states() — the most reliable source
    for ICSD CIFs, which always embed oxidation states in this loop.

    Returns
    -------
    dict  {element: charge}  e.g. {'Na': 1, 'Cl': -1}, or {} if not found.
    """
    oxidation_states = {}
    try:
        with open(cif_path, 'r', encoding='utf-8', errors='ignore') as f:
            lines = f.readlines()
    except FileNotFoundError:
        return {}
    except OSError as e:
        # v1.1: a CIF that cannot be read is not a CIF with no oxidation
        # states in it, and the caller treats the two identically.
        raise ValueError(f'could not read {cif_path}: {e}') from e

    in_loop      = False
    columns      = []
    symbol_col   = None
    oxi_col      = None

    for line in lines:
        ls = line.strip()

        if ls == 'loop_':
            in_loop    = False
            columns    = []
            symbol_col = None
            oxi_col    = None
            continue

        if ls.startswith('_atom_type_'):
            idx = len(columns)
            columns.append(ls)
            if ls == '_atom_type_symbol':
                symbol_col = idx
            elif ls == '_atom_type_oxidation_number':
                oxi_col  = idx
                in_loop  = True
            continue

        if in_loop and columns and not ls.startswith('_'):
            if not ls or ls.startswith('#') or ls.startswith('loop_'):
                in_loop = False
                continue
            parts = ls.split()
            if symbol_col is not None and symbol_col < len(parts):
                raw     = parts[symbol_col]
                element = _re.sub(r'[0-9+\-]+', '', raw)
                element = (element.capitalize() if len(element) > 1
                           else element.upper())
                if oxi_col is not None and oxi_col < len(parts):
                    ox_str = parts[oxi_col]
                    if ox_str not in ['?', '.']:
                        try:
                            oxidation_states[element] = round(float(ox_str))
                        except ValueError:
                            pass

    return oxidation_states


def _oxi_from_library(elements, reduced_formula, library):
    """
    Look up oxidation states by reduced formula in maple_library.json.
    Returns dict or None if formula not found or elements not fully covered.
    """
    overrides = library.get('oxidation_state_overrides', {})
    entry = overrides.get(reduced_formula)
    if entry and isinstance(entry, dict):
        if all(el in entry for el in elements):
            return {el: entry[el] for el in elements}
    return None


def _oxi_from_json_fallback(elements, oxi_json):
    """
    Attempt oxidation state assignment using common_oxidation_states.json.
    Returns dict or None if any element is ambiguous (multiple common states).
    """
    assignment = {}
    for el in elements:
        states = oxi_json.get(el, [])
        if len(states) == 1:
            assignment[el] = states[0]
        else:
            return None
    return assignment

# ── load_structure (v4) ──────────────────────────────────────────────────────
#
# KEY CHANGE from v3: pymatgen's native per-site oxidation state assignment
# is now the FIRST choice after user override. ICSD CIFs embed oxidation
# states in the _atom_site_type_symbol column (e.g., Mn3+, Mn4+), and
# pymatgen correctly assigns these per-site, preserving:
#   - Non-integer states (Pr3.8+ for mixed-valence)
#   - Different states on different sites (Mn3+ on site 1, Mn4+ on site 2)
#   - Charge neutrality
#
# The previous approach read element-level values from _atom_type_oxidation_number,
# which collapsed mixed-valence to a single state per element and broke charge
# balance for ~35% of structures. That is now a fallback, not the default.

def _parse_structures(parser):
    """
    Structures from a CifParser, in the PRIMITIVE cell.

    v1.3: this was `parser.get_structures()`, whose primitive=True default is
    deprecated. MaplePy has always worked in the primitive cell; nothing said
    so, and `parse_structures()` defaults the other way, so a mechanical
    rename at some future pymatgen release would have changed the cell
    without changing a line of intent.

    The choice is not load-bearing for the numbers, which is worth recording.
    Measured on the same CIFs both ways:

        pyrochlore ICSD 109080   primitive    22 sites  Z 2  MAPLE 10173.38
                                 conventional 88 sites  Z 8  MAPLE 10173.38
                                 d_ref 1.9298 and MF 8.4463 in both

        perovskite ICSD 109352   identical either way: 20 sites, Z 4,
                                 MAPLE 3914.11, d_ref 1.9855, MF 3.9007

    MAPLE per formula unit, d_ref and the Madelung factor are invariant; the
    cell and Z change together. What is NOT invariant is anything that counts
    sites - the per-site table gains 66 rows per pyrochlore in the
    conventional cell - so the cell is pinned rather than left to a default.
    """
    if hasattr(parser, 'parse_structures'):
        return parser.parse_structures(primitive=True)
    return parser.get_structures()


def _has_native_oxi_states(structure):
    """
    Check whether pymatgen assigned oxidation states when parsing the CIF.
    Returns True if all sites contain Species (not bare Element) objects.
    """
    from pymatgen.core.periodic_table import Species
    for site in structure:
        for sp in site.species:
            if not isinstance(sp, Species):
                return False
    return True


def _native_charge_balance(structure):
    """
    Compute the total charge using pymatgen's native per-site assignments.
    Handles mixed-occupancy sites correctly via occupancy weighting.
    """
    total = 0.0
    for site in structure:
        for sp, occ in site.species.items():
            if hasattr(sp, 'oxi_state'):
                total += sp.oxi_state * occ
    return total


def load_structure(cif_path, oxidation_states=None, data_dir=None):
    """
    Load a CIF and decorate with oxidation states.

    Mixed-occupancy sites are handled via mean-field charge averaging
    in the downstream compute_maple() function.

    Priority chain for oxidation state assignment:
    1. User-supplied oxidation_states dict          (highest priority)
    2. pymatgen native per-site assignment from CIF (preserves mixed valence,
       non-integer states, and per-site distinctions)
    3. _atom_type_oxidation_number loop in the CIF  (element-level fallback)
    4. maple_library.json formula override           (unambiguous binaries)
    5. common_oxidation_states.json fallback         (single-state elements)
    6. Raises ValueError with a helpful message      (never silently zeros)

    Parameters
    ----------
    cif_path        : str or Path
    oxidation_states: dict, optional  e.g. {'Na': 1, 'Cl': -1}
    data_dir        : str  path to folder containing maple_library.json
                      and common_oxidation_states.json

    Returns
    -------
    pymatgen Structure with oxidation states applied.
    """
    cif_path = str(cif_path)

    # v1.2: None means "wherever the data actually is"; an explicit path that
    # does not exist is a mistake rather than a reason to fall back silently.
    if data_dir is None:
        data_dir = DEFAULT_DATA_DIR
    elif not Path(data_dir).is_dir():
        raise ValueError(f'data_dir does not exist: {data_dir}')

    # ── Load CIF, catching unrecognised element labels ────────────────────
    try:
        from pymatgen.io.cif import CifParser
        parser = CifParser(cif_path, occupancy_tolerance=OCCUPANCY_TOL)
        structures = _parse_structures(parser)
        if not structures:
            raise ValueError("No valid structures parsed from CIF.")
        structure = structures[0]
    except Exception as e:
        if "not a valid Element" in str(e):
            raise ValueError(
                f"Unrecognised element label in CIF: {e}. "
                f"Common causes: D (deuterium) in neutron data, "
                f"or generic labels (M, X) for disordered sites."
            ) from e
        raise

    source = None
    disordered = _is_disordered(structure)

    if disordered:
        _kind, _where = _disorder_detail(structure)
        print(f"  Note: {_kind}"
              f"{'' if _where == 'none' else f' on the {_where} sublattice'}"
              f" detected. Using mean-field charge approximation.")

    # ── Check for unphysical occupancies ──────────────────────────────────
    for site in structure:
        occ_sum = sum(site.species.values())
        if occ_sum > OCCUPANCY_TOL:
            print(f"  WARNING: site occupancy sum = {occ_sum:.3f} "
                  f"(>1.0) at {site.species}. "
                  f"Refinement quality issue.")

    # ── Priority 1: user override ─────────────────────────────────────────
    if oxidation_states is not None:
        structure.add_oxidation_state_by_element(oxidation_states)
        source = 'user'

    # ── Priority 2: pymatgen native per-site assignment ───────────────────
    elif _has_native_oxi_states(structure):
        # pymatgen already assigned Species with oxi_states from the CIF.
        # Check charge balance to confirm they are sensible.
        native_q = _native_charge_balance(structure)
        if abs(native_q) < CHARGE_NEUTRAL_TOL:
            source = 'CIF (per-site, charge-neutral)'
        else:
            # Native states exist but are not charge-neutral.
            # This happens for genuinely non-stoichiometric compounds.
            # Still use them — they are the best available assignment.
            source = (f'CIF (per-site, Σq={native_q:+.2f})')
        # No action needed: structure already has the correct states.

    else:
        # ── pymatgen did not assign oxi states — fall back ────────────────
        # Extract element set
        elements = set()
        for site in structure:
            for sp in site.species:
                el = (sp.element.symbol if hasattr(sp, 'element')
                      else sp.symbol)
                elements.add(el)

        # ── Priority 3: CIF _atom_type loop (element-level) ──────────────
        cif_oxi = _extract_cif_oxidation_states(cif_path)

        if (cif_oxi
                and all(el in cif_oxi for el in elements)
                and any(v != 0 for v in cif_oxi.values())):
            structure.add_oxidation_state_by_element(cif_oxi)
            source = 'CIF (_atom_type, element-level fallback)'

        else:
            # ── Priority 4: maple_library.json ────────────────────────────
            library = _load_maple_library(data_dir)
            reduced = structure.composition.reduced_formula
            lib_oxi = _oxi_from_library(elements, reduced, library)

            if lib_oxi is not None:
                structure.add_oxidation_state_by_element(lib_oxi)
                source = f'maple_library.json ({reduced})'

            else:
                # ── Priority 5: common_oxidation_states.json ──────────────
                oxi_json = _load_oxi_json(
                    Path(data_dir) / 'common_oxidation_states.json'
                )
                json_oxi = _oxi_from_json_fallback(elements, oxi_json)

                if json_oxi is not None:
                    structure.add_oxidation_state_by_element(json_oxi)
                    source = 'common_oxidation_states.json'

                # ── Priority 6: informative failure ───────────────────────
                else:
                    missing = [el for el in elements
                               if el not in (cif_oxi or {})]
                    multi = [el for el in elements
                             if len(oxi_json.get(el, [])) > 1]
                    raise ValueError(
                        f"Could not determine oxidation states for: "
                        f"{missing + multi}.\n"
                        f"  CIF embedded states found for: "
                        f"{sorted(cif_oxi.keys()) if cif_oxi else 'none'}.\n"
                        f"  Elements with multiple common states: "
                        f"{multi}.\n"
                        f"  Reduced formula '{reduced}' not found in "
                        f"maple_library.json.\n"
                        f"  Solution: pass oxidation_states={{...}} "
                        f"explicitly, e.g.:\n"
                        f"    load_structure(path, oxidation_states="
                        f"{{'Mo': 6, 'O': -2}})"
                    )

    # ── Charge-balance check ──────────────────────────────────────────────
    total_charge = _native_charge_balance(structure)
    if abs(total_charge) > CHARGE_NEUTRAL_TOL:
        print(f"  WARNING: not charge-neutral "
              f"(Σq = {total_charge:+.3f} e).\n"
              f"  Source: {source}. Check oxidation states before "
              f"using MAPLE results.")
    else:
        # Build display of oxi states per element
        oxi_display = {}
        for s in structure:
            el = _site_element(s)
            oxi = _site_oxi_state(s)
            if el in oxi_display:
                # Multiple sites with different oxi states — show range
                if isinstance(oxi_display[el], list):
                    if oxi not in oxi_display[el]:
                        oxi_display[el].append(oxi)
                else:
                    if oxi != oxi_display[el]:
                        oxi_display[el] = [oxi_display[el], oxi]
            else:
                oxi_display[el] = oxi

        parts = []
        for el in sorted(oxi_display.keys()):
            v = oxi_display[el]
            if isinstance(v, list):
                vals = '/'.join(f"{x:+.1f}" if x != int(x)
                               else f"{int(x):+d}" for x in sorted(v))
                parts.append(f"{el}={vals}")
            else:
                if v != int(v):
                    parts.append(f"{el}={v:+.2f}")
                else:
                    parts.append(f"{el}={int(v):+d}")

        print(f"  Oxidation states ({source}): " + ", ".join(parts))

    return structure


# ── _find_d_ref ──────────────────────────────────────────────────────────────

def _find_d_ref(structure):
    """
    Shortest cation-anion distance in the structure.

    This is Hoppe's reference distance d₁ (or d_KA) — the normalisation
    distance on which the Madelung constant and MAPLE are based.
    """
    cat_idx = [i for i, s in enumerate(structure)
               if _site_oxi_state(s) > 0]
    ani_idx = [i for i, s in enumerate(structure)
               if _site_oxi_state(s) < 0]

    if not cat_idx or not ani_idx:
        # v1.1: this used to return min(distance from site 0 to anything),
        # which is not a cation-anion distance and may be anion-anion. d_ref
        # normalises the Madelung factor, so a wrong one is not a small error
        # in a diagnostic - it is a different quantity wearing the same name.
        raise ValueError(
            'cannot determine d_ref: the structure has '
            f'{len(cat_idx)} site(s) with positive charge and '
            f'{len(ani_idx)} with negative. Check the oxidation states.')

    d_min = np.inf
    for ci in cat_idx:
        for ai in ani_idx:
            d = structure.get_distance(ci, ai)
            if d < d_min:
                d_min = d
    return float(d_min)


# ── SG 62 origin-choice correction ───────────────────────────────────────

# ── The SG-62 origin correction, removed at v1.3.6 ─────────────────────────
#
# There was a function here, `_fix_sg62_origin`, which built a second
# structure with the 8d oxygen sublattice shifted by (1/2, 1/2, 0), computed
# the Ewald energy of both, and kept whichever was more negative. It is gone,
# and this is the record of why, because a deleted function leaves no trace
# to argue with.
#
# Measured across all 938 perovskites before removing it:
#
#     corrected        44    4.7% of the family, MAPLE moved by up to 8.1%
#     tested and kept 882
#     not applicable   11
#     declined          1
#     pyrochlores       0    it never fired on Fd-3m
#
# and on the eleven corrections examined in detail:
#
#   - both candidates are Pnma, with different interatomic distances and
#     energies 0.3 to 8.1% apart. They are two different structures, not two
#     descriptions of one, so this was a structural edit and not a setting fix
#   - the shortest interatomic contact is IDENTICAL in ten of the eleven, and
#     in ICSD 33482 the shift makes it WORSE, 1.658 A -> 1.462 A, and was
#     applied anyway because the energy was lower. A repair that never
#     improves the geometry is not repairing the geometry
#   - it fired on LaCrO3 220506, whose shortest contact is 1.008 A, and on
#     LuCrO3 138227, one of the RCrO3 series whose real fault is the B cation
#     deposited on 4a: adjusting broken coordinates rather than reporting them
#   - and on TbCrO3 85235, a sound structure agreeing with an independent 2023
#     refinement and additive at 0.056%, whose MAPLE it moved by 2.8%
#
# The selection rule was the Ewald energy, which is the quantity this study
# measures, applied to structures this study is judging.
#
# NOTHING GENERAL REPLACES IT, because there is nothing mis-expanded to
# repair: the deposited structure is the deposited structure. What does the
# work instead is v1.3.3's geometry reporting - d_min_ang, geometry_flag,
# SPLIT_SITE_ANG and SHORT_CONTACT_ANG - and Hopper's codes 2.5 and 2.7. A
# structure that cannot carry a Madelung energy is now reported as such
# rather than quietly improved.
#
# If a repair is ever wanted again, the rule to meet is the one this failed:
# apply it only where the deposited structure FAILS the geometry test and the
# candidate PASSES it. On this dataset that fires on none of the 44.


def _derive_Z(structure):
    """
    Formula units per cell, from the site counts rather than the composition.

    v1.1. `composition.get_reduced_composition_and_factor()` cannot factor a
    NON-STOICHIOMETRIC composition, so it returns Z = 1 and every per-formula
    -unit quantity is inflated by the true Z. Over the 1410-structure
    perovskite and pyrochlore dataset:

        Z = 1 entries                                   172  (12.2%)
        of those, with a fractional subscript           165  (96%)
        Z > 1 entries with a fractional subscript         0  (0%)

    Gd4Cr3.984O12 is not a metadata error; it is a refinement with a partly
    occupied Cr site, and it has four formula units in its cell like every
    other GdFeO3-type perovskite.

    Z is crystallographic, so take it from the crystallography. The number of
    SITES containing each element is an integer whatever the occupancies are,
    and Z divides all of them, so Z is their greatest common divisor. No
    composition arithmetic, no rounding of occupancies, no structure-type
    knowledge.

    Verified on 103 ICSD CIFs: identical to composition reduction on all 95
    where reduction works, and 4 rather than 1 on all 8 where it does not -
    every one a 20-site perovskite. No disagreement in the other direction.

    Falls back to the composition factor only when the structure has no sites
    to count, which cannot happen for a parsed CIF but is not worth an
    exception.
    """
    counts = {}
    for site in structure:
        for sp in site.species:
            el = sp.element.symbol if hasattr(sp, 'element') else sp.symbol
            counts[el] = counts.get(el, 0) + 1
    if not counts:
        _, z_float = structure.composition.get_reduced_composition_and_factor()
        return max(1, int(round(z_float)))
    z = 0
    for n in counts.values():
        z = _math.gcd(z, int(n))
    return max(1, z)


# ── compute_maple ────────────────────────────────────────────────────────────

def compute_maple(structure, verbose=True):
    """
    Compute partial MAPLE values for all sites in the structure.

    Uses pymatgen's EwaldSummation for the electrostatic energy.
    Per-site contributions are the row sums of the energy matrix,
    which sum to the total Ewald energy without double-counting.

    For mixed-occupancy sites, the occupancy-weighted mean charge is used.

    Sign convention
    ---------------
    pymatgen energies are negative (bound state).
    MAPLE is reported positive, following Hoppe's convention.

    Parameters
    ----------
    structure : pymatgen Structure with oxidation states
    verbose   : bool

    Returns
    -------
    dict with keys:
        total_maple_kcal, per_site, Z, d_ref, madelung_factor,
        disordered, structure
    """
    disorder_kind, partial_sublattice = _disorder_detail(structure)
    disordered   = disorder_kind != 'ordered'


    # ── SG 62 origin-choice correction ────────────────────────────────────
    # ── Ewald summation ───────────────────────────────────────────────────
    # v1.3.6: on the structure as deposited. The origin correction that used
    # to run first, and hand its summation down, is gone; see the record
    # above.
    ewald = EwaldSummation(structure)
    energy_matrix = ewald.total_energy_matrix
    per_site_eV   = energy_matrix.sum(axis=1)

    # ── Formula units per cell (Z) ────────────────────────────────────────
    Z = _derive_Z(structure)

    # ── Conversion: eV/site → kcal/mol/site ──────────────────────────────
    per_site_maple = np.abs(per_site_eV) * EV_TO_KCAL_MOL

    # ── Total MAPLE per formula unit ──────────────────────────────────────
    total_maple_kcal = np.abs(ewald.total_energy) * EV_TO_KCAL_MOL / Z

    # ── Reference distance ────────────────────────────────────────────────
    d_ref = _find_d_ref(structure)

    # ── Geometry ──────────────────────────────────────────────────────────
    # v1.3.2: measured, reported, and never used to drop anything.
    d_min, geometry_flag, geometry_status = _geometry_status(structure)

    # ── Per-site data ─────────────────────────────────────────────────────
    per_site_data = []
    for i, site in enumerate(structure):
        oxi     = _site_oxi_state(site)
        maple_i = float(per_site_maple[i])

        pmc = (maple_i * d_ref / (MAPLE_FACTOR * abs(oxi))
               ) if oxi != 0 else None

        reduced = (maple_i / (oxi ** 2) / d_ref
                   ) if oxi != 0 else None

        per_site_data.append({
            "site_index"      : i,
            "element"         : _site_element(site),
            "oxidation_state" : round(oxi, 4),
            "mixed_site"      : len(site.species) > 1,
            "frac_x"          : round(float(site.frac_coords[0]), 6),
            "frac_y"          : round(float(site.frac_coords[1]), 6),
            "frac_z"          : round(float(site.frac_coords[2]), 6),
            "maple_kcal_mol"  : round(maple_i, 3),
            "pmc"             : round(pmc, 5)     if pmc is not None else None,
            "reduced_maple"   : round(reduced, 4) if reduced is not None else None,
        })

    # ── Madelung factor ───────────────────────────────────────────────────
    #
    # v1.1: THE CONVENTION, WRITTEN DOWN. The mean charges below are means
    # over SITES, not over stoichiometry and not weighted by multiplicity.
    # For ABO3 with two trivalent cations the two agree; for a 2+/4+
    # perovskite the site mean is 3, and for the pyrochlore 16d/16c/48f/8b
    # counts it is a different average again. Nothing here is changed,
    # because the classification and every published figure rest on this
    # definition - but it is a choice, it was undocumented, and it scales the
    # axis on which the Z = 1 population was identified. It should be checked
    # against Hoppe's own normalisation before any future version moves it.
    try:
        oxi_states = [_site_oxi_state(s) for s in structure]
        z_pos = [z for z in oxi_states if z > 0]
        z_neg = [z for z in oxi_states if z < 0]
        if not z_pos or not z_neg:
            madelung_factor = None
        else:
            mean_zp = np.mean(z_pos)
            mean_zn = abs(np.mean(z_neg))
            madelung_factor = (total_maple_kcal * d_ref
                               / (MAPLE_FACTOR * mean_zp * mean_zn))
    except (TypeError, ValueError, ZeroDivisionError, AttributeError):
        madelung_factor = None

    result = {
        "total_maple_kcal" : round(total_maple_kcal, 2),
        "per_site"         : per_site_data,
        "Z"                : Z,
        "d_ref"            : round(d_ref, 4),
        "madelung_factor"  : (round(madelung_factor, 4)
                              if madelung_factor is not None else None),
        "disordered"       : disordered,
        "disorder_status"  : disorder_kind,
        "partial_sublattice": partial_sublattice,
        "d_min_ang"        : round(d_min, 4),
        "geometry_flag"    : geometry_flag,
        "geometry_status"  : geometry_status,
        "structure"        : structure,
    }

    if verbose:
        comp = structure.composition.reduced_formula
        sg   = structure.get_space_group_info()[0]
        _where = ('' if partial_sublattice in ('none', None)
                  else f' ({partial_sublattice})')
        tag  = (f"  [MEAN-FIELD: {disorder_kind}{_where}]"
                if disordered else "")
        print(f"\n{'─'*60}")
        print(f"  Compound  : {comp}  ({sg}){tag}")
        print(f"  Sites     : {len(structure)}  |  Z = {Z}")
        print(f"  d_ref     : {d_ref:.4f} Å")
        print(f"  Geometry  : {geometry_status}")
        mf_str = f"{madelung_factor:.4f}" if madelung_factor is not None else "n/a"
        print(f"  MF        : {mf_str}")
        print(f"  MAPLE     : {total_maple_kcal:.1f} kcal/mol  "
              f"({total_maple_kcal * KCAL_TO_KJ:.1f} kJ/mol)")
        print(f"{'─'*60}")

    return result


# ── results_to_dataframe ─────────────────────────────────────────────────────

def results_to_dataframe(maple_result):
    """Convert compute_maple() output to a tidy pandas DataFrame."""
    df = pd.DataFrame(maple_result["per_site"])

    comp = maple_result["structure"].composition.reduced_formula
    sg   = maple_result["structure"].get_space_group_info()[0]
    df["compound"]        = comp
    df["space_group"]     = sg
    df["Z"]               = maple_result["Z"]
    df["d_ref_ang"]       = maple_result["d_ref"]
    df["madelung_factor"] = maple_result["madelung_factor"]
    df["total_maple"]     = maple_result["total_maple_kcal"]
    df["disordered"]      = maple_result["disordered"]
    df["disorder_status"] = maple_result.get("disorder_status")
    df["partial_sublattice"] = maple_result.get("partial_sublattice")
    df["d_min_ang"]       = maple_result.get("d_min_ang")
    df["geometry_flag"]   = maple_result.get("geometry_flag")
    df["geometry_status"] = maple_result.get("geometry_status")

    cols = ["compound", "space_group", "Z", "d_ref_ang", "madelung_factor",
            "total_maple", "disordered", "disorder_status",
            "partial_sublattice", "d_min_ang", "geometry_flag",
            "geometry_status", "site_index", "element",
            "oxidation_state", "mixed_site",
            "frac_x", "frac_y", "frac_z",
            "maple_kcal_mol", "pmc", "reduced_maple"]
    return df[cols]